-- 1413: шесть новых туров «Лагуны Экспедиции» с её сайта.
--
-- ── Основание ─────────────────────────────────────────────────────────────
-- Сверка по отчёту наблюдения 08.11 (1408) нашла на laguna-expedition.ru туры,
-- которых у нас нет. Вопрос владельцу 08.11 «заводить?» — ответ «да».
-- Страницы сняты 08.11.2026 под именем VedarSiteWatch:
--   36212 «Вулканы Камчатки (4 дня)» — от 45 000, выезды 09.11.2026–20.06.2027;
--   36214 «Вулканы Камчатки (5 дней)» — от 60 000, те же месяцы;
--   37577 «Камчатка на максимум: летний маршрут» — от 169 000, 15.06–30.09.2027;
--   37584 «Камчатка: летний экспресс» — от 160 000, 15.06–30.09.2027;
--   41610 «Камчатка на максимум: зимний маршрут» — от 90 000, 13.11.2026–10.04.2027;
--   51446 «Вулканы Камчатки 4 дня (новогодние праздники)» — от 85 000,
--         25.12.2026–08.01.2027.
-- Седьмая страница из отчёта, 41467 «Индивидуальные экскурсии по Вашим
-- пожеланиям», на 08.11 отвечает 404, и цены у такой нет — не переносится
-- (как 41424 в 1339).
--
-- ── Как поля взяты с сайта — правила 1339 ─────────────────────────────────
--   • название — заголовок страницы; адрес тура — 'lagexp-' и латинская часть
--     адреса страницы;
--   • цена — «от N руб.» календаря (одно число на страницу), за человека;
--     в price_note — дата цены, набор группы и обязательный банкет 31.12, если
--     страница их называет;
--   • вместимость — наибольшее «Осталось N мест» календаря; длительность — дни
--     программы × 24;
--   • краткое описание — первая строка «Описания», вторая (если есть) — в «О
--     туре»; у 37577 туда же строка «Примечаний» о реконструкции санатория;
--   • программа по дням «День N. <заголовок>»; из текста дня убраны строки
--     «Экипировка» (они в «что взять»), реквизиты гостиниц («Номер реестровой
--     записи … ИНН … ОГРН», ссылка на реестр), «ИЛИ» между подписанными
--     вариантами и строка доплаты с ценой (она в «не входит»); знак «!» в
--     начале строки снят; остальное — слова оператора;
--   • «входит» — «В стоимость включено», у 37577 и строки «При размещении в
--     … в стоимость входит»; «не входит» — «В стоимость не включено», каждая
--     «Дополнительная услуга» как «за доплату: … - цена» и «страховка», где её
--     нет среди услуг. В услугах выправлена только типографика: кавычки,
--     «2х» → «2-», «welcom сэт» → «welcome-сет»;
--   • безопасность — только сказанное страницей: изменение программы по погоде,
--     выбор варианта дня туроператором, продолжительность по погоде,
--     рекомендуемый возраст 5–65 (37577, 37584), перенос и отмена по прогнозу и
--     сообщениям МЧС (41610);
--   • сложность easy — где страница пишет «небольшие физические нагрузки»
--     (37577, 41610), у остальных NULL; зависимость от погоды — TRUE у всех;
--   • вид активности — как у похожих туров 1339: пакеты «Вулканы Камчатки» —
--     sightseeing (как 50713), «Камчатка на максимум» и «летний экспресс» —
--     jeep_safari (как 41599).
--
-- ── Чего здесь нет ────────────────────────────────────────────────────────
--   • снимков — их кладёт следующая миграция тем же порядком, что 1343
--     (отбор глазами, без лиц, в хранилище);
--   • дат и сезона, условий отмены, точки сбора, координат — как в 1339:
--     поля пусты («не записано»);
--   • главного места (main_place_id): все шесть — многодневные по районам
--     (город, Халактырский пляж, перевалы, источники), одного места у них нет.
--     Так же 1344 оставила без связи осенний и новогодние маршруты «Лагуны»;
--     причина записана в KNOWN_UNLINKED сторожа
--     tests/unit/tour-main-place-in-migrations.test.ts.
--
-- Идемпотентна: тур вставляется, только если карточка laguna-expedition есть и
-- адреса тура ещё нет. Повтор ничего не меняет. Исход — WARNING в конце.

BEGIN;

INSERT INTO operator_tours (
  operator_id, title, slug, short_description, description,
  location_type, activity_type, location_name, latitude, longitude,
  base_price, currency, price_unit, min_participants, max_participants,
  duration_hours, duration_type, multi_day_count,
  weather_dependent, difficulty, is_active, is_published,
  program, included, not_included, what_to_bring, safety_notes,
  pickup_type, pickup_details, meeting_point,
  photos, tour_image,
  price_note, source_url,
  created_at, updated_at
)
SELECT
  p.id, v.title, v.slug, v.short_d, v.descr,
  v.loc_type, v.act_type, v.loc_name, NULL, NULL,
  v.price, 'RUB', v.unit, 1, v.max_p,
  v.dur_h, v.dur_type, v.days,
  v.weather, v.diff, TRUE, TRUE,
  v.program, v.included, v.not_incl, v.bring, v.safety,
  NULL, NULL, NULL,
  ARRAY[]::text[], NULL,
  v.price_note, v.source_url,
  NOW(), NOW()
FROM partners p
CROSS JOIN (VALUES
  -- 36212
  ('Вулканы Камчатки (4 дня)'::text, 'lagexp-vulkany-kamchatki-4-dnya'::text,
   'Проживание в спа-отеле «Лагуна» (3 ночи) + трансфер из/в аэропорт(а) + 2 экскурсии с обедами.'::text,
   NULL::text,
   'volcano'::text, 'sightseeing'::text, 'Паратунка, спа-отель «Лагуна»'::text,
   45000::numeric, 'per_person'::text, 20::int,
   96::numeric, 'multi_day'::text, 4::int,
   TRUE, NULL::text,
   '[{"title": "День 1. Привет, Камчатка!", "text": "Место встречи – Международный аэропорт «Елизово» имени Витуса Беринга. Мы встретим Вас в любое, но заранее согласованное время. Трансфер из аэропорта до спа-отеля «Лагуна» (~30 км). По пути сделаем остановку у памятника «ЗНР – здесь начинается Россия», где сделаем первые фотографии на фоне вулканов. Прибытие в спа-отель «Лагуна», свободное время на отдых и акклиматизацию. Размещение в номерах после 15:00. СПА-отель «Лагуна» – место отдыха на Камчатке, где комфорт и современность идеально сочетаются с первозданной красотой природы. Отель расположен прямо на берегу озера Микижа, с которого открывается великолепный вид на вулканы. На территории: свои рестораны, пекарня «Булочная», спа-центр с термальным источником и панорамной парной, аквацентр с открытым бассейном, торговые павильоны «ReKa» и «Икра Краб»."}, {"title": "День 2. Петропавловск-Камчатский + Халактырский пляж", "text": "Завтракаем по системе «шведский стол» в ресторане отеля. Начинаем знакомство с Камчатским краем с посещения его центра – города Петропавловска –Камчатского (~50 км). В ходе программы мы побываем на смотровых площадках, откуда открываются потрясающие панорамные виды на город, бухту и окружающие вулканы. Узнаем об истории края, коренных жителях и особенностях архитектуры. А ещё мы обязательно посетим один из музеев: 1 вариант: Экскурсия в единственном музее в России, который посвящён вулканам – «Вулканариум». Тут расскажут про «огненное сердце Камчатки», предоставят возможность взвесить обсидиан и пемзу, а также ударить в волшебный бубен (для самых сокровенных желаний). 2 вариант: Экскурсия в Визит-центре Кроноцкого заповедника, где погрузимся в мир заповедной природы: узнаем историю создания одного из старейших заповедников в России, увидим скульптуры животных, созданные на 3D-принтере, побываем в «берлоге медведя», подсмотрим за жизнью морских млекопитающих и узнаем интересные факты о кальдере вулкана Узон. Выбор варианта музея посещения определяется туроператором. Обед (салат, суп, сэндвич). После отправляемся на реальный край земли – Халактырский пляж (~50 км). Там холодные воды Тихого океана накатывают на чёрный песчаный пляж, а самые смелые смогут прогуляться босиком в прибойной волне. Свободное время на берегу, чтобы в полной мере почувствовать дыхание самого большого в мире океана. Общая продолжительность экскурсионного дня: 9 – 10 часов. Возвращение в спа-отель «Лагуна» (~65 км). Свободный вечер, рекомендуем отправиться на ужин в ресторан отеля «MISHKA» (самостоятельно, за дополнительную плату)."}, {"title": "День 3. Перевал Вилючинский", "text": "Завтракаем по системе «шведский стол» в ресторане отеля. Нас ждёт одна из визитных карточек Камчатки – вулкан Вилючинский. К нему мы отправимся на легендарном вездеходе Sever Truck и будем любоваться горным гигантом, который возвышается над окрестностями на 2173 м. Для этого поднимемся на Вилючинский перевал, на высоту 840 метров над уровнем моря, откуда открывается потрясающая панорама на целых 10 вулканов, 5 из которых действующие! Именно здесь мы встретим Гамулов – духов вулканов. Обед на природе (салат, суп, сэндвич). Общая продолжительность экскурсионного дня: 3 часа. Продолжительность экскурсии зависит от погодных условий и может быть увеличена. Возвращение в спа-отель «Лагуна». Свободный вечер, рекомендуем отправиться в павильон «ReKa» на территории отеля для покупки камчатских сувениров (самостоятельно, за дополнительную плату)."}, {"title": "День 4. До новых встреч!", "text": "Завтракаем по системе «шведский стол» в ресторане отеля. Трансфер из отеля в аэропорт ко времени Вашего вылета. По дороге мы заедем на местный рынок морепродуктов, чтобы Вы смогли купить свежие камчатские деликатесы."}]'::jsonb,
   ARRAY['проживание в спа-отеле «Лагуна 4*» (3 ночи)', 'завтраки по системе «шведский стол» в ресторане отеля', 'трансфер из/в аэропорт(а)', 'транспортное и экскурсионное обслуживание по программе', 'пользование аквацентром', 'обед в дни выезда на экскурсии']::text[],
   ARRAY['авиабилеты до г. Петропавловск-Камчатский', 'ранний заезд', 'ужины', 'сувениры', 'икра', 'дополнительные экскурсии', 'за доплату: приветственный набор из эклеров с камчатскими деликатесами и настоек из местных ягод - 7 000 руб.', 'за доплату: заезд на дикие Карымшинские термальные источники - 4 000 руб.', 'за доплату: замена обеда на крабовый пикник, цена с человека - 2 500 руб.', 'за доплату: доп. ночь, 2-местный номер в корпусе «Голубое озеро» - 7 500 руб.', 'за доплату: доп. ночь в категории «Глазастик» - 11 000 руб.', 'за доплату: доп. ночь, 2-местный (Форест) - 11 000 руб.', 'за доплату: замена трансфера с отель-аэропорт на отель-Петропавловск-Камчатский - 3 000 руб.', 'за доплату: замена сборного трансфера из (в) аэропорт на индивидуальный, цена за авто - 3 000 руб.', 'страховка']::text[],
   ARRAY['непродуваемая одежда', 'термобельё', 'головные уборы', 'солнцезащитные очки', 'теплая одежда', 'трекинговая обувь', 'шапка']::text[],
   ARRAY['Программа тура может быть изменена в связи с погодными условиями и внештатными ситуациями.', 'Продолжительность экскурсии на Вилючинский перевал зависит от погоды и может быть увеличена.']::text[],
   'Цена от 45 000 ₽ за человека по сайту оператора на 08.11.2026. Тур состоится при наборе группы от 2 человек.'::text,
   'https://laguna-expedition.ru/tours/36212-vulkany-kamchatki-4-dnya'::text),

