       price, unit, max_p, dur_h, dur_type, days, weather, diff,
       program, included, not_incl, bring, safety, price_note, source_url)
WHERE p.slug = 'laguna-expedition'
  AND NOT EXISTS (SELECT 1 FROM operator_tours t WHERE t.slug = v.slug);

-- Исход вслух: шесть туров у «Лагуны Экспедиции». Иное (карточки нет, адрес
-- тура занят другим оператором) называется, а не молчит.
DO $$
DECLARE
  v_p int;
  v_n int;
BEGIN
  SELECT count(*) INTO v_p FROM partners WHERE slug = 'laguna-expedition';
  IF v_p <> 1 THEN
    RAISE WARNING '[1413] карточек laguna-expedition: % (нужна одна, её заводит 1323) — туры не заведены', v_p;
    RETURN;
  END IF;
  SELECT count(*) INTO v_n FROM operator_tours t
    JOIN partners p ON p.id::text = t.operator_id::text
   WHERE p.slug = 'laguna-expedition' AND t.deleted_at IS NULL
     AND t.source_url ~ '/tours/(36212|36214|37577|37584|41610|51446)-';
  IF v_n <> 6 THEN
    RAISE WARNING '[1413] у «Лагуны Экспедиции» % из 6 новых туров (адрес тура занят другим оператором или тур удалён?)', v_n;
  END IF;
END $$;

COMMIT;
